<?php require __DIR__.'/_layout.php';$db=x1_db();if($_SERVER['REQUEST_METHOD']==='POST'){x1_check_csrf();if($db)x1_db_exec("UPDATE notifications SET status='read',read_at=? WHERE id=?",[date('c'),(string)$_POST['id']]);header('Location:notifications.php');exit;}$rows=$db?x1_db_all('SELECT * FROM notifications ORDER BY created_at DESC LIMIT 1000'):[];top(tr('Notification Center','Centro de Notificações'));?><section class="card hero"><div class=eyebrow>OPERATIONS INBOX</div><h2><?=tr('Health, sync, activation and security events in one place','Eventos de health, sync, activation e segurança num único local')?></h2></section><section class=section><table><tr><th>Time</th><th>Level</th><th>Title</th><th>Message</th><th>Status</th><th></th></tr><?php foreach($rows as $x):?><tr><td><?=h($x['created_at'])?></td><td><?=h($x['level'])?></td><td><?=h($x['title'])?></td><td><?=h($x['body'])?></td><td><?=h($x['status'])?></td><td><?php if($x['status']!=='read'):?><form method=post><input type=hidden name=csrf value="<?=x1_csrf()?>"><input type=hidden name=id value="<?=h($x['id'])?>"><button><?=tr('Read','Lida')?></button></form><?php endif?></td></tr><?php endforeach?></table></section><?php bottom();